STAN model:

 data {
  int<lower=1> K;
 int<lower=1> D;
 int<lower=1> N;
 matrix<lower=-1,upper=1>[N,D] y;
 matrix[N,K] x;
 }
parameters {
 matrix[K,D] beta;
 cholesky_factor_corr[D] L_Omega;
 matrix<lower=0>[N,D] abs_ystar; //latent variable
 }
transformed parameters {
 matrix[N,D] z;
 z <- (y .* abs_ystar);
 }
model {
 L_Omega ~ lkj_corr_cholesky(1);
 to_vector(beta) ~ normal(0,5);
 {
  matrix[N,D] beta_x;
  beta_x <- x * beta;
  for (n in 1:N)
   z[n,] ~ multi_normal_cholesky(beta_x[n,], L_Omega);
  }
 }
generated quantities {
 matrix[D,N] z_new;
 matrix[D,D] Omega;
