Thanks very much! Really appreciated. In case anyone else needs it, the following worked perfectly for us!

data{
  int N;
  real phi[N];
}

parameters {

  real<lower=0> kappa[N];
  real<lower=0> a;
  real<lower=0> b;
}

model{
    for (i in 1:N){
      if (kappa[i] < 100){
        phi[i] ~ von_mises(0,kappa[i]);
      } else{
        phi[i] ~ normal(0,sqrt(1/kappa[i]));
      }
        kappa[i] ~ gamma(a,b);
    }
    a ~ gamma(2,1);
    b ~ gamma(2,1);
}

