needs to become

parameters {
  real b;
  real<lower=0> shape;
  real<lower=0> mu;

  real<lower=0, upper = 1> alpha;
  real<lower=0, upper = 1 - alpha> phi;
}

which does not have the tmp variable. Then you can push what you had for transformed parameters into the model block

model {
  vector[N] eta;
  real lambda;
  eta[1] <- log(Y[1]); // log(Y[1]) could be calculated in transformed data
  lambda <- 1 - alpha - phi;

  for (t in 2:N)

    eta[t] <- X[t] * b + lambda * mu + phi * eta[t - 1] + alpha * Y[t - 1];
  Y ~ neg_binomial_2_log(eta, shape); // this should really be excluding Y[1]
  alpha ~ normal(0.5, 0.5);
  // don't use a gamma(0.01, 0.01) prior for shape
}

